import{_ as p,c as e,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"睽","description":"高島易斷 - 睽","frontmatter":{"title":"睽","description":"高島易斷 - 睽"},"headers":[],"relativePath":"classics/takashima/038.md","filePath":"classics/takashima/038.md"}'),i={name:"classics/takashima/038.md"};function l(n,a,d,t,s,c){return r(),e("div",null,[...a[0]||(a[0]=[h('<h1 id="睽" tabindex="-1">睽 <a class="header-anchor" href="#睽" aria-label="Permalink to “睽”">​</a></h1><h2 id="睽-1" tabindex="-1">睽 <a class="header-anchor" href="#睽-1" aria-label="Permalink to “睽”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>睽：小事吉。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦傳》曰：“家道窮必乖，故受之以睽。睽者，乖也。”《睽》則眾心離散，不可以興大事，若小事則力可獨任，不待眾舉，雖《睽》尚可為也，故曰“小事吉”。《睽》卦上下互《既濟》，《既濟》《彖傳》曰“亨，小者亨也”，謂所亨特其小者；此卦曰“小事吉”，吉亦惟在小事耳。《兌》為小，故第言小不言大。要之乖《睽》之世，不足以成大事也，可知矣。</p><h2 id="象辭" tabindex="-1">象辭 <a class="header-anchor" href="#象辭" aria-label="Permalink to “象辭”">​</a></h2><p>上火下澤，睽，君子以同而異。</p><h2 id="象辭注" tabindex="-1">象辭注 <a class="header-anchor" href="#象辭注" aria-label="Permalink to “象辭注”">​</a></h2><p>卦象皆女也，卦體為火澤，炎上潤下，其用各異，故曰《睽》。君子法之，於同處見其象，於異處別其用，不黨同以背道，亦不立異以悖俗。“以同而異”者，譬如聲色貨財，為人所同欲，而或去或受，不敢苟同於人者，是其所以獨異也。此可見君子之“以同而異”也。火澤同卦，而炎潤各異其性者，亦猶是焉。</p><h2 id="占斷" tabindex="-1">占斷 <a class="header-anchor" href="#占斷" aria-label="Permalink to “占斷”">​</a></h2><p>○　問時運：目下氣運顛倒，惟宜正以處之。</p><p>○　問戰徵：軍情不協，上下異趣，宜防《睽》散。</p><p>○　問功名：上下不通，功名難望。</p><p>○　問營商：貨價上落懸殊，能以人棄我取，尚有小利可望。</p><p>○　問疾病：病在上下焦，胸氣隔絕，上有火，下有溼，醫治棘手。</p><p>○　問家宅：此宅天盤地盤皆動，闔家上下不利，急宜遷避。</p><p>○　問婚姻：有二女皆願受聘，大者性躁急，小者性寬柔。擇而娶之。</p><p>○　問訟事：即可罷散。</p><p>○　問六甲：生女。</p><h2 id="初九解" tabindex="-1">初九解 <a class="header-anchor" href="#初九解" aria-label="Permalink to “初九解”">​</a></h2><p>初居《兌》體之下，自《家人》上爻來，《家人》上曰“終吉”，故《睽》初曰“悔亡”。爻屬《震》，辰在卯，上值房，房為天駟，故稱“馬”；初動而上，舍我而去，故云“喪”。然四與初同德，他無正應，姑聽其去，勢必復來，故云“勿逐，自復”。下互《離》，《離》性猛烈可畏，故曰“惡人”。《兌》為見，《離》亦為見，是《離》之惡人既來求見，《兌》若拒而不見，未免嫉之太甚，必致咎也。《兌》姑與之相見，如陽貨欲見孔子，孔子以禮往拜之旨也，故得“無咎”。蓋失馬而逐之，愈逐愈逸，見惡人而激之，愈激愈乖，是以“勿逐”而“自復”，“見惡人”而不避，可以免咎矣。能以無心而應物，則《睽》無不合也。《象傳》曰“以避咎也”，蓋不以避為避，避而有咎，則以不避為無咎可知也。</p><h2 id="初九佔" tabindex="-1">初九佔 <a class="header-anchor" href="#初九佔" aria-label="Permalink to “初九佔”">​</a></h2><p>○　問時運：好運初來，災悔已退，雖有喪失，不必計慮，即有惡人來侵，不必拒絕，自然無咎。</p><p>○　問戰徵：初次開戰，雖有小敗，後必大勝，強敵亦不能害我也。無咎。</p><p>○　問營商：新作貿易，失而必復，無須憂慮也。來者不拒，無須計較也。目下未見盡利，後必大亨。</p><p>○　問功名：現下雖無災悔，未得成名，必待明年，至二爻得其巷遇，斯獲顯達。</p><p>○　問家宅：閹宅平順，無悔，無咎。</p><p>○　問失物：不必尋覓，自得。</p><p>○　問婚姻：現下未成，待到六月，或到六年，必就，吉。在上九“非寇，婚媾”之辭。</p><p>○　問訟事：所訟必直，無咎。</p><p>○　問六甲：生女。</p><h2 id="初九案例" tabindex="-1">初九案例 <a class="header-anchor" href="#初九案例" aria-label="Permalink to “初九案例”">​</a></h2><p>友人某來請佔氣運，筮得《睽》之《未濟》。</p><p>斷曰：此卦火性上升，澤性下降，彼我之情不洽，名之曰《睽》。《睽》者違也。今足下佔氣運，而得初爻，初爻地位處最下，孤立無應，可知足下夙性孤高寡與，得失勿較，即有素所心惡之人，彼苟有求而來，亦不至拒而不納。以初爻處《兌》之始，外卦為《離》，《兌》悅也，《離》，明也，悅而又明，必能識人善惡，又復和光同塵，不為過甚。卦象《睽》不終《睽》，故得無悔無咎。二爻曰“遇主於巷”，足下至明年，必有登進之望。</p><h2 id="九二解" tabindex="-1">九二解 <a class="header-anchor" href="#九二解" aria-label="Permalink to “九二解”">​</a></h2><p>“主”者，君也，指六五而言；“巷”，裡中道，從邑，從共，謂裡中所共往來者也。二處《睽》失位，所如不合，與五正應，二居《兌》中，五居《離》中，《兌》《離》皆為見，知二五均有相見之意，邂逅於巷，是不期遇而適相遇也。君臣相遇，《睽》而終合，咎何有焉？《象傳》曰“未失道也”，謂不假遠涉，自得相遇於巷；巷，道路也，即《論語》所謂“遇諸途”者是也。</p><h2 id="九二佔" tabindex="-1">九二佔 <a class="header-anchor" href="#九二佔" aria-label="Permalink to “九二佔”">​</a></h2><p>○　問時運：卦值乖《睽》，運本不佳，近始得有絕好際遇，往必有慶。</p><p>○　問戰徵：二五相敵，內為我兵，五為敵兵，曲巷相遇，白刃相接，此戰未分勝負。</p><p>○　問營商：巷字從共，必是合夥共謀之業，當有一財主相遇，共為經營之象。</p><p>○　問功名：正是風雲際遇之時。</p><p>○　問家宅：此宅在曲巷之內，近有貴人來會，相晤為歡，大慶。</p><p>○　問疾病：得遇良醫，無咎。</p><p>○　問婚姻：《詩》所詠“邂逅相遇，適我願兮”，此男婦私情，非正配也。</p><p>○　問六甲：生女。</p><h2 id="九二案例" tabindex="-1">九二案例 <a class="header-anchor" href="#九二案例" aria-label="Permalink to “九二案例”">​</a></h2><p>明治二十三年，佔文部省教育準則，筮得《睽》之《噬嗑》。</p><p>斷曰：此卦火性上炎，澤性下潤，以上下懸殊，故名曰《睽》。今佔教育準則，而得二爻，二爻處《睽》失位，將無所安，譬諸近時文部省之教育，專以歐美為法，以智與理為主，我國舊時道德之教，亦同二之處失位，幾將委棄不用也。凡留學歐洲生徒，歸朝之後，各為教師，以教育子弟；在此輩生徒，本不知我國古來之教，敦綱紀，重名分，自足卓立萬世，培育群才者也。乃厭故喜新，如陳相之見許行，盡棄其學而學焉，又相率我國子弟一從其教，餘實憂之。為撰《道德本原》一篇，明治二十三年十月十八日，請謁山縣總理大臣，乃陳述其說。是日各縣知事，亦適在坐，鹹相傾聽，大臣曰，子之所論，切中時弊，命餘往謁芳川文部大臣。餘即日謁文部省，復申前說，閱日天皇召問二大臣，遂下教育之敕，以餘鄙論上達天聽，何幸如之！爻辭所謂“遇主於巷”者，適相合也。《易》理先機，神妙如此！《道德本原》節略：昔者我邦以神、儒、佛三道，為道德之標準，維持世道人心，自西學日興，舊學日廢，若不究其由來，未足施救濟之策也。以餘所見，仁義忠孝節操廉恥八字，實為儒道之要旨。明治八年中，文部省議廢漢學科，以斥儒教，厥後政略所及，迄至今日，陷溺日深。在文部省亦初無廢意，因定各學科年限卒業，諮問於漢學教師，教師答曰：洋學非我所知，在漢學，雖生涯專修，未有究竟，難定年限。因之議廢。餘謂此迂儒之論也，豈不問孔子所云十五志學，三十而立，孟子所云“幼而學之，壯而行之”是學皆在幼時。三十曰壯，則行所學以濟時也。程子謂《中庸》之書，善讀者，玩索而有得，終身用之有不能盡，不言終身學之而不盡，其於普通科，豈無卒業之期哉！俗儒不知時務，妄作迂論，遂至切要之學，廢置不講，以致今日之禍，罪不容於死。雖然，文部省亦有罪焉。當時俗儒，雖有此議，必繫心醉西學，不識道德之本原，其在文部大臣以下，滿朝名臣賢相，皆出於漢學之門，何以頓忘此躬修之實學乎？實為遺憾！語曰“上之所好，下有甚焉”者，從此浮薄子弟，蔑視漢學，不知其如何而可。道德兇而廉恥滅，小則判一身之邪正，中則關一家之盛衰，大則系天下之安危，其害有不可勝言者矣。既往不可復咎，為今之計，回狂瀾於既倒，以矯正世道人心，上安天子之宸襟，下增國民之福利。道德之教，所關甚巨，地方長官，已具文申詳文部大臣，定以儒教主義，為後來學科之準則。講究儒教主義，德之本原，實今日之急務也。設定二種教育，一曰真理，一曰現理。真理者，出於天理之公，合夫性命之正，即所謂正心、誠意、修身之學，形而上之教也；現理者，成於人類之私，得夫氣形之利，即所謂立身、興家、富國之學，形而下之教也。古人曰“衣食足而知禮節”，又曰“無恆產者無恆心”，實人世之常態，此真現理二種，不可一日或缺者也。其略如此。</p><h2 id="六三解" tabindex="-1">六三解 <a class="header-anchor" href="#六三解" aria-label="Permalink to “六三解”">​</a></h2><p>上互《坎》，《坎》為輿，下互《離》，《離》為牛。“無初有終”，遇剛也。《離》亦為見，上下互《既濟》，《既濟》初有曳輪之辭，故曰“見輿曳”。“掣”，掣曳也，即牽掣之意。“輿”指三，“曳”指四，“掣”指二。三居上下之交，其位不當，四曳之，二掣之，是曳其輿於前，又掣其牛於後也。“天”，胡氏安定謂“天當作而”，篆文而與天字形似，即禮“髡刑曰而”。“劓”，截鼻也，發屬心而主火，鼻屬肺而主金，此爻《兌》金值《離》火，金火相剋，故有發鼻受傷之象。《兌》為刑人，故曰其人“天且劓”。三爻處下卦之終，當《睽》違之時，以陰居陽，履非其位，與上相應；上居《離》極，《離》火性烈，不合則相傷，合則相得，遇雨疑亡，《睽》終合矣，故曰“無初有終”。《象傳》曰“遇剛也”，剛指四，即上之“遇雨”也；四互《坎》，《坎》為雨，四又中立不倚，故曰“剛”，謂四能釋上之疑，使之終合也。</p><h2 id="六三佔" tabindex="-1">六三佔 <a class="header-anchor" href="#六三佔" aria-label="Permalink to “六三佔”">​</a></h2><p>○　問時運：運不得當，恐有刑傷之災；三年後，得有好運。</p><p>○　問營商：與人不合，非特不能獲利，防有刑獄之厄，待後可成。</p><p>○　問功名：左掣右肘，動輒得咎，安能成名？晚運則佳。</p><p>○　問戰徵：車脫馬逸，兵敗將亡，不能前進，必待應軍得力，得以始敗終勝。</p><p>○　問婚姻：初因男家疑忌，未免受辱，終得疑釋完婚。</p><p>○　問家宅：此宅地位不當，前後左右，皆有牽制，宅中之人，時有頭面傷殘之禍，以朝山向午，《離》火來克。宜改向朝西《兌》位，乃吉。</p><p>○　問疾病：必是面上有瘡，久後自愈。</p><p>○　問訟事：不免刑厄，終則自解。</p><p>○　問失物：後可尋得。</p><p>○　問六甲：生女，防面有傷痕。</p><h2 id="六三案例" tabindex="-1">六三案例 <a class="header-anchor" href="#六三案例" aria-label="Permalink to “六三案例”">​</a></h2><p>一日友人某氏來，曰某貴顯託僕以一事，請佔其吉凶。筮得《睽》之《大有》。</p><p>斷曰：《彖傳》謂《睽》“火動而上，澤動而下”，上下相背，是以成《睽》；又曰“男女睽而其志通”，是初《睽》而終合，即三爻所謂“無初有終”之旨也。今足下代佔，而得三爻，三爻曰：“見輿曳，其牛掣，其人天且劓。無初有終。”玩爻辭，謂人在輿中，曳者欲前，掣者欲後，前後牽引，不得上行，且有面鼻受傷之象。卦體則為女子，料知某貴顯所委託者，必為女子之事也。初次向說，必有上下之人阻隔，致生紛爭，所委不成，足下對某貴顯，亦覺面無光彩。《象》曰“遇剛”，看來當再得一剛直之人，與之幫說，事乃得合，故曰“無初有終”。貴顯覓一小妾，本屬小事，《彖》曰“小事吉”，終必有吉也。</p><p>明治二十九年冬至，佔三十年農商務省施政實況，筮得《睽》之《大有》。</p><p>斷曰：玩爻象，牛本足以駕輿，曰“曳”，曰“掣”，是反為牽制，不能前行也；輿不能進，欲強行之，其人反遭損傷之患。爻象如是。今佔農商務省施政實況，而得此爻，我邦欲法歐美各邦農商之實例，施之內地，奈富商安於坐食，不願航海遠行，貧商欲行而苦無資本。今雖絲局茶廠，仿用器械，無如販運外洋，或為關稅所困，或為船險所阻，外洋貿易，向與內地不同。農業我國土地狹隘，以人口之半為農計之，一人僅不遇二段，是以歐美便宜之法，施之內地，實不能用，若強用之，皆歸遊手無產之徒，害憂更甚，惟北海道新墾之田可用耳。及一切雜項商務，亦多不便於行，猶是火炎上，澤潤下，兩不相洽，終必《睽》乖而不合用也。幸農商務省曲為設法，使老練者興工業，附商品，給以一定之商標，俾各品得以信用，又獎勵富商，使之興海陸保險會社、銀行支店，以奮起商業，可得漸見有效，謂之“無初有終”。</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>四居《離》卦之始，《離》為目，《說文》“目不相視為睽”。“孤”，謂獨立無輔也。其情既《睽》，其勢又孤，故曰“睽孤”。“元夫”指初，四與初所處之時，同在《睽》也，所居之位，同在始也，其象同，故其志同。四以無應，得初為同志，初在卦首，故稱“元”；四陰位，初陽位，故四以初為夫；且初《震》爻，《震》為元夫，故曰“遇元夫”。四變《損》，《損》曰“有孚”；四之五為《中孚》，《中孚》五爻曰“有孚攣如”，有交孚之象焉，故曰“交孚”。“厲，無咎”，謂時當《睽》乖，幸而得孚，雖厲無咎。《象》以“志行”釋之，謂四之志，得此“交孚”，乃可行也。</p><h2 id="九四佔" tabindex="-1">九四佔 <a class="header-anchor" href="#九四佔" aria-label="Permalink to “九四佔”">​</a></h2><p>○　問時運：性情孤介，不合時宜，幸得同志，差足免咎。</p><p>○　問戰徵：孤軍深入，幾致危殆，幸而獲救，可以無咎。</p><p>○　問營商：孤客遠行，貨物不合銷路，進退兩難，得遇故鄉舊友，方可脫售，平安無咎。</p><p>○　問功名：命運孤寒，難望顯達，無咎而已。</p><p>○　：問家宅：宅在孤村僻壤，惟有樵夫野老來往而已。</p><p>○　問疾病：病是目疾，得遇良醫，可以無咎。</p><p>○　問六甲：生女。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>明治二年十二月，晦，餘借海軍省蒸氣船飛龍丸，運載支那米，赴南部宮古，臨發筮得《睽》之《損》。</p><p>餘臨事，每自占筮以為常，特此爻“無咎”之言，不復介意。乘船之後，平時忙碌之身，變為閒散，追念昔年，在南部狎暱一妓，擬待抵埠登岸，招呼船長等驚豔稱奇，同為一醉。一涉痴想，夜不成眠，閱三日，船抵宮古，號炮一發，村吏來迎，中有舊友二人，遂竊告之，使彼往招。既而率眾上陸，剪燈置酒，圍坐會，頻番催呼，答而不來，甚為失望。夜深客散，乃拍手遽問，此妓出曰：妾來此久矣，自愧醜不堪侍娛，故不入也。餘亦驚駭曰：何老至此也！既復沉思，蓋相別已十八年皋。《易》曰“老妻士夫”，可羞可笑。妓復泣告曰：近因罹疾，容顏頓變，生機亦窘，有死而已。餘追思往昔未免有情，誰能遣此？乃贈米二十包，付以券書，彼深喜而辭去。是適符“睽孤，遇元夫，交孚，厲，無咎”之象也。</p><h2 id="六五解" tabindex="-1">六五解 <a class="header-anchor" href="#六五解" aria-label="Permalink to “六五解”">​</a></h2><p>五居君位，時當《睽》乖，故有悔。“宗”指二，五與二應，五處《離》中，二至四為《離》，《離》與離合，是宗也。二曰“遇主”，以五為主，五曰“厥宗”，以二為宗，是君臣會合，故“悔亡”。二動體《噬嗑》，《噬嗑》二爻曰“噬膚”、“無咎”，按膚謂膚肉，為柔而易噬。嗑，合也，二居柔位，猶言柔而易合。膚肉，猶骨肉也，蓋指“厥宗”而言。大宗伯以飲食之禮親宗族兄弟，即此“厥宗噬膚”之義也。二往得食，故“有慶”。合族以食，復何《睽》？二五“交孚”，故“悔亡”而無咎。</p><h2 id="六五佔" tabindex="-1">六五佔 <a class="header-anchor" href="#六五佔" aria-label="Permalink to “六五佔”">​</a></h2><p>○　問時運：劣運已退，得與同宗共事，可以無咎。</p><p>○　問戰徵：可勇躍前往，無咎。</p><p>○　問營商：防合夥者有侵食之患，然徑行而往，終得有利。</p><p>○　問功名：得有同宗相助，乃能獲慶。</p><p>○　問家宅：此宅是宗族舊屋，往居有慶。</p><p>○　問疾病：是肌膚之疾，易治也。</p><p>○　問婚姻：二與五為正應，是親戚舊家，成則有慶。</p><p>○　問六甲：生女。</p><h2 id="六五案例" tabindex="-1">六五案例 <a class="header-anchor" href="#六五案例" aria-label="Permalink to “六五案例”">​</a></h2><p>明治二十三年春，佔眾議院，筮得《睽》之《履》。</p><p>斷曰：五為君位，二為臣位，二五相應，即見君臣相合。相合則言聽計從，有會議之象焉。卦名曰《睽》，《睽》，乖也，違也，知會議必有《睽》異不合者。“厥宗”者，議院有二，上曰貴族院，下曰眾議院，貴族院多是同姓諸侯，眾議院亦間有同姓臣庶。“噬膚”者，謂議成得以酒食會飲也。五既居尊親二，二得荷寵事五，可見上下之志，得因《睽》而通也。</p><h2 id="上九解" tabindex="-1">上九解 <a class="header-anchor" href="#上九解" aria-label="Permalink to “上九解”">​</a></h2><p>上居外卦之極，孤高獨立，故亦稱“睽孤”。上互《坎》，為疑，為豕，為車，為鬼，為孤，皆《坎》象也。《離》為目，為見。《兌》澤汙下，象途泥。因《睽》成孤，因孤生疑，本未嘗有豕也，未嘗有鬼也，未嘗有車也，《睽》則目視不明，而疑心暗起，若見有豕之負塗焉，若見有車之載鬼焉，積疑成象，變端百出。疑鬼者，忽又疑為寇焉，則將張《離》之弧而射之，既而諦審所見，先所見豕邪、鬼邪、寇邪，忽又變矣；上變《歸妹》，則“婚媾”也，先之張弧，後即脫之矣。《坎》又為雨，故曰“遇雨”。上處《離》極，火烈煙騰，不可向邇，遇雨則火熄，可以往也，故曰“往，遇雨，則吉”。《象》以“疑亡”釋之，謂群疑消亡，見聞皆真，睽孤自合矣。</p><h2 id="上九佔" tabindex="-1">上九佔 <a class="header-anchor" href="#上九佔" aria-label="Permalink to “上九佔”">​</a></h2><p>○　問時運：正當交運脫運之時，切宜息心定慮，毋動妄想，妄想一端，幻形百端，防生疑病。</p><p>○　問戰徵：營位太高，軍力太孤，防有疑兵來襲。</p><p>○　問營商：目下貨價，變遷百出，上落不一；時當盛夏，來客稀少，必待秋雨一通，可以獲利。</p><p>○　問功名：現在牛怪蛇神，變動不一，待十年後，出《蹇》入《解》，可許發解。</p><p>○　問婚姻：前因疑忌不睦，後得完好，吉。</p><p>○　問家宅：此宅有變，防有鬼祟，遇婚嫁喜事，可以解釋。</p><p>○　問疾病：杯弓蛇影，因疑成病，得破其疑，病自霍然。</p><p>○　問六甲：生女。</p><h2 id="上九案例" tabindex="-1">上九案例 <a class="header-anchor" href="#上九案例" aria-label="Permalink to “上九案例”">​</a></h2><p>東京大家某氏夫人，偕女訪餘別莊，曰：良人頃患氣鬱之疾，醫藥無效，養嗣某，即為此女之夫，性遊蕩，不克承家，妾等實所憂慮，請幸一佔。筮得《睽》之《歸妹》。</p><p>斷曰：卦體下《兌》上《離》，炎上者動而愈上，潤下者動而愈下，上下不合，故卦為《睽》。卦象為“二女同居，其志不同行”，又曰“男女睽而其志通”，是以內三爻言《睽》，外三爻言《睽》而合，是始《睽》後合之象也。上九居《睽》之極，因疑生《睽》，愈睽愈疑，目之所見，積疑成象，豕也，車也，鬼也，寇也，恍若歷歷在前，實則一一皆幻。天下事杯弓蛇影，因疑兆禍者，類如斯也。今夫人為尊君之病患，與養嗣之行止，特來請佔，筮得《睽》之上爻，知其病之由來，與所佔之本意，皆由猜疑一念而生也。尊君為養嗣，不克承家，日夕疑慮，以致火氣上衝，溼氣下鬱，上下不通，遂成是疾。“雨”者，下降也，病得大小便一通，自然安愈。君家養嗣，餘所深知，文學志操，向超流俗，緣其性情風雅，偶或招妓置酒，怡情於花柳之場，此亦雅人深致，何足為怪？夫人等因之生疑，始則猜忌，繼則交謫，終則反目，一切所聞所見，如爻象所謂豕車鬼寇，悉現其形。凡床第間恩愛之私，雲雨之夢，久已《睽》隔，斯疑者益疑，《睽》者益睽，男女之志，必不通矣。上居《離》火之極，極則必反，炎上當反而潤下為雨，夫人等亦宜反而思之，務勸令媛，溫柔以接之，《兌》悅以事乏。如物之枯者得雨而復甦，早《睽》不終《睽》矣。《彖傳》所云“男女睽而其志通”也，正合此佔。</p><p>明治二十四年四月十日，餘清晨無事，閒閱新聞及雜書，未幾意倦，拋書而起。愛此風日晴和，遊興頓發，將赴近縣，探賞春光。臨行偶試一筮，得《睽》之《歸妹》。</p><p>斷曰：爻辭曰“睽孤”，猶示餘孤身獨行也。曰“見豕”、“載鬼”、“張弧”、“脫弧”，言其目見之無定形，猶示餘遊跡之無定所也。餘是日出遊，憩息於神奈川停車場，或赴橫須賀，或赴箱根湯本，意猶未定，至登車乃決往箱根。車中適遇東京舊友某氏赴大孤，並坐談《易》，興味頗好，餘遂改意趨大孤。翌日食後，出遊市中，將就舊肆，閱覽古書，乃過心齋橋，訪鹿田書店，問以《易》書珍本。主人出示松井羅州所著《周易解故》，此書餘往年遍覓不得，今得購之。又示以松井氏所著《周易釋故》，及直勢中洲所著《周易大傳》等，是皆讀《易》家所珍。書面有小島氏藏書一印，餘叩其出處，主人曰：昨購於西京古書肆，此書皆系小島氏舊藏，氏沒後，其子不能讀父書，故鬻之。餘曰：如子之外，猶有同購者乎？主人曰：西京麩屋町書林某，及東京書林某，相與分買之也。餘乃悉以其價購之，後赴西京，又就麩屋町書肆，凡小島氏遺本，又悉購之。歸東訪書肆琳琅閣，又得小島氏《易》書三種，於是小島氏遺書，悉皆歸餘。餘益感《易》辭之精切也。爻所謂“載鬼一車”者，非鬼，乃書也；“遇雨”者，舊友也，即車中所遇之舊友也；所謂“遇雨則吉”者，此也。</p>',110)])])}const m=p(i,[["render",l]]);export{b as __pageData,m as default};
